import './tools/economy-audit/source-loader.mjs';
import fs from 'node:fs';
import {createHash} from 'node:crypto';
const slug='trauma-head-spine-extremities';
const packet=JSON.parse(fs.readFileSync(`docs/research/question-topic-${slug}-20261111.json`,'utf8'));
const ledger=JSON.parse(fs.readFileSync(`docs/research/sources-question-topic-${slug}-20261111.json`,'utf8'));
const module=await import(`./packages/clinical-content/src/question-topic-${slug}-20261111.ts`);
const {SYNTHETIC_CLINICAL_RELEASE:release}=await import('./packages/clinical-content/src/synthetic-content.ts');
const {QUESTION_SHIP_MANIFEST:manifest}=await import('./packages/clinical-content/src/question-ship-manifest.ts');
const prefix='QUESTION_TOPIC_TRAUMA_HEAD_SPINE_EXTREMITIES_';
const drift=packet.assignment.baseline.inputHashes.filter(input=>createHash('sha256').update(fs.readFileSync(input.file,'utf8')).digest('hex')!==input.currentSha256);
const md=fs.readFileSync(`docs/research/question-topic-${slug}-20261111.md`,'utf8');
const output={jsonParse:'PASS',explicitImport:'PASS',cases:module[prefix+'CASES'].length,questions:module[prefix+'QUESTIONS'].length,concepts:module[prefix+'TESTED_CONCEPTS'].length,sources:ledger.sources.length,claims:ledger.claims.length,assignedSourceHashDrift:drift.length,markdownFencesBalanced:(md.match(/^```/gm)||[]).length%2===0,manifest:{id:manifest.id,rows:manifest.accepted.length,cases:release.cases.length,nodes:release.cases.flatMap(c=>c.decisionNodes).length,concepts:release.concepts.length},reviewStatus:packet.reviewStatus,finalTypecheckExit:packet.finalHandoff.validation.typecheckExitCode};
if(drift.length||!output.markdownFencesBalanced)throw new Error(JSON.stringify(output));
console.log(JSON.stringify(output,null,2));

